function pushServiceIdsForSelectedMappingRow() {
  const mappingSheet = tm_getRequiredSheet_(SERVICE_CONFIG.SHEETS.MAPPING);
  const rowNumber = tm_getActiveRowNumber_();
  tm_assertNotHeaderRow_(rowNumber);

  const values = mappingSheet.getDataRange().getValues();
  const headers = values[0];
  const indexMap = tm_buildHeaderIndexMap_(headers);
  const row = values[rowNumber - 1];

  const taskId = Number(tm_getRowValue_(row, indexMap, 'Task ID')) || 0;
  const contactId = Number(tm_getRowValue_(row, indexMap, 'Hidden Contact ID')) || 0;
  const taskStatus = tm_getRowValue_(row, indexMap, 'Task Status');

  if (!taskId) throw new Error('Service Contact push requires a valid Task ID.');
  if (!contactId) throw new Error('Service Contact push requires a resolved Hidden Contact ID. No write attempted.');

  const statusCheck = tm_checkTaskStatusAllowedToPush_(taskStatus);
  if (!statusCheck.allowed) throw new Error('Service Contact push blocked. ' + statusCheck.blockReason);
  if (typeof getStrivenTaskSnapshotById_ !== 'function') throw new Error('Service Contact push requires getStrivenTaskSnapshotById_.');

  const before = getStrivenTaskSnapshotById_(taskId, {});
  if (Number(before.conId || 0) === contactId) {
    return { status: 'ALREADY_CORRECT', writesPerformed: false, taskId: taskId, contactId: contactId, readBackVerified: true };
  }

  const payload = { Id: taskId, RequestedBy: { Id: contactId, Type: 'contact' } };
  if (typeof updateStrivenTaskById_ === 'function') {
    updateStrivenTaskById_(taskId, payload);
  } else if (typeof patchStrivenTaskById_ === 'function') {
    patchStrivenTaskById_(taskId, payload);
  } else {
    throw new Error('Service Contact push has no proven Striven task PATCH helper.');
  }

  const delays = [500, 1200, 2500];
  let after = null;
  for (let i = 0; i < delays.length; i++) {
    Utilities.sleep(delays[i]);
    after = getStrivenTaskSnapshotById_(taskId, {});
    if (Number(after.conId || 0) === contactId) {
      return { status: 'PUSHED_AND_VERIFIED', writesPerformed: true, taskId: taskId, contactId: contactId, readBackVerified: true };
    }
  }

  throw new Error('Service Contact PATCH completed but RequestedBy Contact read-back did not match. No retry attempted.');
}

